-- GENERATED by gen_mxh3_vault.py -- models are generated, never hand-edited.
--   SAT_PROVIDER_TARIFF
--   anchor      : HUB_PARTY
--   grain       : Multi-Active SCD2 (data_7.js sats[].hist)
--   child key   : Service Code
--   feeders     : 1 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 4 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_PARTY_BK__K0)) as HUB_PARTY_HK,
        coalesce(nullif(trim(SERVICE_CODE),''),'') as SERVICE_CODE,
        SERVICE_NAME as SERVICE_DESCRIPTION,
        TARIFF_RATE_PER_UNIT as TARIFF_RATE,
        TARIFF_AMOUNT as PACKAGE_RATE,
        'MAXI_HLTH_CLM_VW_DATA_CLAIM_DETAIL_LIST_OF_COVERS_ENTITY_HEADS_ENTITY_GRID_ROWS_ROW_ATTRIBUTES_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_clm_cd_loc_eh_egr_rattr_pv') }}
    where HUB_PARTY_K0__EMIT
)), hashed as (select *,
        case when SERVICE_DESCRIPTION is not null or TARIFF_RATE is not null or PACKAGE_RATE is not null
             then md5(upper(coalesce(SERVICE_DESCRIPTION::varchar,'') || '||' || coalesce(TARIFF_RATE::varchar,'') || '||' || coalesce(PACKAGE_RATE::varchar,'')))
        end as SAT_PROVIDER_TARIFF_HASHDIFF
    from feeders)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PROVIDER_TARIFF_HASHDIFF is not null
  and SERVICE_CODE is not null
